from typing import Callable, Iterable, Any
def _is_outperform(basefunc: Callable, targetfunc: Callable, args: Iterable[Any], repeats: int = 1000, samples: int = 10):
    import timeit
    from scipy.stats import ttest_ind
    # Warmup, drop result.
    _ = [timeit.timeit(lambda: basefunc(*args), number=repeats) for _ in range(samples)]
    rt0 = [timeit.timeit(lambda: targetfunc(*args), number=repeats) for _ in range(samples)]
    rt1 = [timeit.timeit(lambda: basefunc(*args), number=repeats) for _ in range(samples)]

    # Test rt0/rt1 have identical average values with p 0.05.
    stat, p = ttest_ind(rt0, rt1, equal_var=True)
    print(f'p={p}, {sum(rt0)}, {sum(rt1)}')
    if p > 0.05:
        return False
    return sum(rt0) < sum(rt1)

#compare
args = [[5, 1, 5, 2, 5, 3, 5, 4]]
assert _is_outperform(baseline, find_repeated_element, args, samples=100)

