#include <iostream>
#include <math.h>
#include <unordered_map>
#include <vector>

static const double EPS = 1e-8;

class CSRMatrix {
public:
  std::vector<double> values;
  std::vector<int> col_indices;
  std::vector<int> row_ptr;
  int numRows, numCols;
  CSRMatrix(int rows, int cols) : numRows(rows), numCols(cols) {
    row_ptr.resize(rows + 1, 0);
  }
  std::vector<std::vector<double>> to_dense() {
    std::vector<std::vector<double>> res(numRows,
                                         std::vector<double>(numCols, 0.0));
    for (int row = 0; row < numRows; ++row) {
      for (int index = row_ptr[row]; index < row_ptr[row + 1]; ++index) {
        res[row][col_indices[index]] = values[index];
      }
    }
    return res;
  }
  void from_dense(const std::vector<std::vector<double>> &matrix) {
    numRows = matrix.size();
    numCols = matrix[0].size();
    row_ptr.resize(numRows + 1, 0);
    values.clear();
    col_indices.clear();
    row_ptr[0] = 0;
    for (size_t i = 0; i < matrix.size(); ++i) {
      for (size_t j = 0; j < matrix[i].size(); ++j) {
        if (fabs(matrix[i][j]) > EPS) {
          col_indices.emplace_back(j);
          values.emplace_back(matrix[i][j]);
        }
      }
      row_ptr[i + 1] = values.size();
    }
  }
};

void sparseMatrixMultiply(const CSRMatrix &A, const CSRMatrix &B,
                          CSRMatrix &C) {
  if (A.numCols != B.numRows) {
    throw std::out_of_range("A.numCols != B.numRows");
  }
  C.numRows = A.numRows;
  C.numCols = B.numCols;
  C.row_ptr.resize(A.numRows + 1, 0);
  C.row_ptr[0] = 0;
  for (int row = 0; row < A.numRows; ++row) {
    std::unordered_map<int, double> row_result;
    for (int index = A.row_ptr[row]; index < A.row_ptr[row + 1]; ++index) {
      const int &colA = A.col_indices[index];
      const double &valA = A.values[index];
      // M1[row][colA] = valA;
      // find colB that have M2[colA][colB] = valB
      for (int k = B.row_ptr[colA]; k < B.row_ptr[colA + 1]; ++k) {
        const int &colB = B.col_indices[k];
        const double &valB = B.values[k];
        row_result[colB] += valA * valB;
      }
    }
    for (const auto &iter : row_result) {
      C.col_indices.emplace_back(iter.first);
      C.values.emplace_back(iter.second);
    }
    C.row_ptr[row + 1] = C.values.size();
  }
}

