#include <atomic>
#include <cassert>
#include <iostream>
#include <memory>

std::vector<std::vector<double>>
multiply(const std::vector<std::vector<double>> &a,
         const std::vector<std::vector<double>> &b) {
  if (a[0].size() != b.size()) {
    throw std::out_of_range("A.numCols != B.numRows");
  }
  std::vector<std::vector<double>> res;
  res.resize(a.size(), std::vector<double>(b[0].size(), 0));
  for (int i = 0; i < a.size(); ++i) {
    for (int k = 0; k < b[0].size(); ++k) {
      for (int j = 0; j < a[0].size(); ++j) {
        res[i][k] += a[i][j] * b[j][k];
      }
    }
  }
  return res;
}

void print(const std::vector<std::vector<double>> &a) {
  for (int i = 0; i < a.size(); ++i) {
    for (int j = 0; j < a[i].size(); ++j) {
      printf("%lf%c", a[i][j], " \n"[j + 1 == a[i].size()]);
    }
  }
}

void testcase() {
  std::vector<std::vector<double>> A{
      {0, 1, 2, 3},
      {2, 3, 4, 5},
  };
  std::vector<std::vector<double>> B{
      {0, 1},
      {2, 3},
      {4, 5},
      {6, 7},
  };
  auto res = multiply(A, B);
  printf("dense matrix result:\n");
  print(res);

  CSRMatrix csrA(2, 4), csrB(4, 2), csrC(2, 2);
  csrA.from_dense(A);
  csrB.from_dense(B);
  sparseMatrixMultiply(csrA, csrB, csrC);
  printf("csrA matrix:\n");
  print(csrA.to_dense());
  printf("csrB matrix:\n");
  print(csrB.to_dense());
  printf("csrC matrix:\n");
  print(csrC.to_dense());

  assert(res == csrC.to_dense());
}

int main() {
  testcase();
  return 0;
}

