#include <type_traits>
#include <vector>
#include <cassert>

template <typename T, size_t kSize = 8>
class AutoVec {
 public:
  AutoVec() = default;

  AutoVec(size_t size, const T default_value = T()) {
    if (size > 0) {
      std::uninitialized_fill_n(&(stack_vec_[0]), std::min(size, kSize), default_value);
      if (size > kSize) {
        heap_vec_.resize(size - kSize, default_value);
      }
    }
  }

  AutoVec(const AutoVec &other)
      : num_stack_size_(other.num_stack_size_),
        heap_vec_(other.heap_vec_) {
    if (num_stack_size_ > 0) {
      std::uninitialized_copy_n(&(other.stack_vec_[0]), num_stack_size_,
                                &(stack_vec_[0]));
    }
  }

  AutoVec &operator=(const AutoVec &other) {
    DtorVec(&(stack_vec_[0]), num_stack_size_);
    if (other.num_stack_size_ > 0) {
      std::uninitialized_copy_n(&(other.stack_vec_[0]), other.num_stack_size_,
                                &(stack_vec_[0]));
    }
    num_stack_size_ = other.num_stack_size_;
    heap_vec_ = other.heap_vec_;
    return *this;
  }

  AutoVec(AutoVec &&other)
      : num_stack_size_(other.num_stack_size_),
        heap_vec_(std::move(other.heap_vec_)) {
    if (num_stack_size_ > 0) {
      std::uninitialized_move_n(&(other.stack_vec_[0]), num_stack_size_,
                                &(stack_vec_[0]));
    }
  }

  AutoVec &operator=(AutoVec &&other) {
    DtorVec(&(stack_vec_[0]), num_stack_size_);
    if (other.num_stack_size_ > 0) {
      std::uninitialized_move_n(&(other.stack_vec_[0]), other.num_stack_size_,
                                &(stack_vec_[0]));
    }
    num_stack_size_ = other.num_stack_size_;
    heap_vec_ = std::move(other.heap_vec_);
    return *this;
  }

  ~AutoVec() { Clear(); }

  const T &operator[](size_t idx) const {
    if (idx < kSize) {
      return stack_vec_[idx];
    } else {
      return heap_vec_[idx - kSize];
    }
  }

  T &operator[](size_t idx) {
    if (idx < kSize) {
      return stack_vec_[idx];
    } else {
      return heap_vec_[idx - kSize];
    }
  }

  template <class... Args>
  void EmplaceBack(Args &&...args) {
    if (num_stack_size_ < kSize) {
      ::new (&(stack_vec_[num_stack_size_++])) T(std::forward<Args>(args)...);
    } else {
      heap_vec_.emplace_back(std::forward<Args>(args)...);
    }
  }

  void PushBack(T &&v) {
    if (num_stack_size_ < kSize) {
      ::new (&(stack_vec_[num_stack_size_++])) T(std::move(v));
    } else {
      heap_vec_.push_back(std::move(v));
    }
  }

  void PushBack(const T &v) {
    if (num_stack_size_ < kSize) {
      ::new (&(stack_vec_[num_stack_size_++])) T(v);
    } else {
      heap_vec_.push_back(v);
    }
  }

  void PopBack() noexcept {
    assert(num_stack_size_ > 0);
    if (!heap_vec_.empty()) {
      heap_vec_.pop_back();
    } else {
      DtorVec(&(stack_vec_[--num_stack_size_]), 1);
    }
  }

  T &Front() {
    assert(num_stack_size_ > 0);
    return stack_vec_[0];
  }

  const T &Front() const {
    assert(num_stack_size_ > 0);
    return stack_vec_[0];
  }

  T &Back() {
    assert(num_stack_size_ > 0);
    if (num_stack_size_ <= kSize) {
      return stack_vec_[num_stack_size_ - 1];
    } else {
      return heap_vec_.back();
    }
  }

  const T &Back() const {
    assert(num_stack_size_ > 0);
    if (num_stack_size_ <= kSize) {
      return stack_vec_[num_stack_size_ - 1];
    } else {
      return heap_vec_.back();
    }
  }

  size_t Size() const { return num_stack_size_ + heap_vec_.size(); }

  bool IsEmpty() const { return Size() == 0; }

  void Resize(size_t new_size, const T default_value = T()) {
    size_t old_size = Size();
    if (new_size < old_size) {
      if (new_size > kSize) {
        heap_vec_.resize(new_size - kSize);
      } else {
        heap_vec_.clear();
        DtorVec(&stack_vec_[new_size], kSize - new_size);
      }
    } else if (new_size > old_size) {
      if (new_size > kSize) {
        heap_vec_.resize(new_size - kSize, default_value);
      } else {
        std::uninitialized_fill_n(&(stack_vec_[old_size]),
                                  new_size - old_size, default_value);
      }
    }
  }

  void Clear() {
    heap_vec_.clear();
    DtorVec(&(stack_vec_[0]), num_stack_size_);
  }

 private:
  static void DtorVec(T *t, size_t num) {
    if (!std::is_trivially_destructible<T>::value &&
        std::is_destructible<T>::value && num > 0) {
      while (num > 0) {
        t->~T();
        t++;
        --num;
      }
    }
  }

  size_t num_stack_size_ = 0;
  T stack_vec_[kSize];
  std::vector<T> heap_vec_;
};

