#include <atomic>
#include <cassert>

class RwSpinLock {
 public:
  RwSpinLock(): lock_state_(static_cast<int64_t>(0)) {}

  void RLock() {
    while (true) {
      int64_t expected = lock_state_.load(std::memory_order_acquire);
      while (expected >= 0 &&
             !lock_state_.compare_exchange_weak(expected, expected + 1,
                                                std::memory_order_acquire,
                                                std::memory_order_relaxed)) {
        AsmVolatilePause();
      }
      if (expected >= 0) {
        return;
      }
      AsmVolatilePause();
    }
  }

  void RUnLock() {
    int64_t rv = lock_state_.fetch_sub(1, std::memory_order_release);
    assert(rv > 0);
  }

  void WLock() {
    int64_t expected = 0;
    while (!lock_state_.compare_exchange_weak(expected, -1,
                                              std::memory_order_acquire,
                                              std::memory_order_relaxed)) {
      expected = 0;
      AsmVolatilePause();
    }
  }

  void WUnLock() {
    int64_t expected = -1;
    while (!lock_state_.compare_exchange_weak(expected, 0,
                                              std::memory_order_acquire,
                                              std::memory_order_relaxed)) {
      assert(expected == -1);
      AsmVolatilePause();
    }
  }

  int64_t ReadParallel() const {
    auto rp = lock_state_.load(std::memory_order_acquire);
    return rp < 0? 0: rp;
  }

 private:
  static void AsmVolatilePause() {
#if defined(__i386__) || defined(__x86_64__)
    asm volatile("pause");
#elif defined(__aarch64__)
    asm volatile("wfe");
#elif defined(__powerpc64__)
    asm volatile("or 27,27,27");
#endif
  }

  std::atomic<int64_t> lock_state_;
};

