Question: Write a Golang code to achieve the following function.
Find the greatest perfect square number less than the nth Fibonacci number
The function signature is `func maxSquareNumber(n int) int`

Answer:
```go
import (
	"fmt"
	"math"
)

func maxSquareNumber(n int) int {
	if n <= 2 {
		return 0
	}

	fibs := []int{0, 1}
	var maxSquare int

	for i := 2; i <= n; i++ {
		fibs = append(fibs, fibs[i-1]+fibs[i-2])
	}

	fib := fibs[len(fibs)-1]
	perfectSquares := make([]int, 0)
	for i := 1; i <= int(math.Sqrt(float64(fib))); i++ {
		perfectSquares = append(perfectSquares, i*i)
	}

	maxSquare = 0
	for _, square := range perfectSquares {
		if square < fib {
			maxSquare = square
		} else {
			break
		}
	}

	return maxSquare
}
