import java.nio.ByteBuffer;
import java.nio.ByteOrder;
public class ByteReader {
    public static int readTwoBytesAsInt(byte[] data, int index) {
        if (index < 0 || index + 1 >= data.length) {
            return -1;
        }
        ByteBuffer bb = ByteBuffer.allocate(2);
        bb.order(ByteOrder.BIG_ENDIAN);
        bb.put(data[index]);
        bb.put(data[index + 1]);
        return bb.getShort(0) & 0xFFFF;
    }
    public static void main(String[] args) {
        byte[] exampleData = {0x00, 0x01, 0x02, 0x03, 0x04};
        System.out.println(readTwoBytesAsInt(exampleData, 1)); 
        System.out.println(readTwoBytesAsInt(exampleData, -1)); 
        System.out.println(readTwoBytesAsInt(exampleData, 4)); 
    }
}

