import java.util.ArrayList;
public class EvenNumbersFilter {
    public static int[] filterEvenNumbers(int[] numbers) {
        ArrayList<Integer> evenNumbersList = new ArrayList<>();
        for (int number : numbers) {
            if (number % 2 == 0) {
                evenNumbersList.add(number);
            }
        }
        int[] evenNumbers = new int[evenNumbersList.size()];
        for (int i = 0; i < evenNumbersList.size(); i++) {
            evenNumbers[i] = evenNumbersList.get(i);
        }
        return evenNumbers;
    }
    public static void main(String[] args) {
