using System.Text;
using System.Diagnostics;
using System.Numerics;
using System;
using System.Collections.Generic;
using System.Linq;
class DataAnalysis
{
    public static double CalculateStandardDeviation(List<int> numbers)
    {
        if (numbers == null || numbers.Count == 0)
        {
            throw new ArgumentException("The numbers list cannot be null or empty.", nameof(numbers));
        }
        double mean = numbers.Average();
        double sumOfSquaredDifferences = numbers.Select(num => (num - mean) * (num - mean)).Sum();
        double standardDeviation = Math.Sqrt(sumOfSquaredDifferences / numbers.Count);
        return standardDeviation;
    }
