using System.Security.Cryptography;
using System.Text;
using System.Diagnostics;
using System.Numerics;
using System;
using System.Collections.Generic;
using System.Linq;
class NumberSorter {
    public static string SortWordedNumbers(string numberWords) {
        Dictionary<string, int> numberMapping = new Dictionary<string, int> {
            {"one", 1}, {"two", 2}, {"three", 3}, {"four", 4},
            {"five", 5}, {"six", 6}, {"seven", 7}, {"eight", 8},
            {"nine", 9}, {"ten", 10}
        };
        var sortedNumbers = numberWords.Split(' ')
                                        .Select(word => numberMapping[word])
                                        .OrderBy(num => num)
                                        .Select(num => numberMapping.FirstOrDefault(x => x.Value == num).Key);
        return String.Join(" ", sortedNumbers);
    }
    public static void Check() {
        Debug.Assert(SortWordedNumbers("three one five") == "one three five");
        Debug.Assert(SortWordedNumbers("nine eight seven") == "seven eight nine");
        Debug.Assert(SortWordedNumbers("two four six") == "two four six");
        Console.WriteLine("All checks passed!");
    }

}

