import json

def max_score(data):
    d = json.loads(data)

    user_scores = {}
    for elem in d:
        uid = elem['uid']
        score = elem['score']
        if uid not in user_scores:
            user_scores[uid] = [score]
        else:
            user_scores[uid].append(score)

    user_avg_scores = [(x, sum(y) * 1.0 / len(y)) for x, y in user_scores.items()]
    user_avg_scores.sort(key=lambda x: x[1], reverse=True)

    return user_avg_scores[0][0]

