using System.Security.Cryptography;
using System.Text;
using System.Diagnostics;
using System.Numerics;
using System;
using System.Collections.Generic;
using System.Linq;
class SquaredOddsSorter
{
    public static List<int> FilterSquareSortDesc(List<int> numbers)
    {
        return numbers.Where(num => num % 2 != 0)
                      .Select(num => num * num)
                      .OrderByDescending(num => num)
                      .ToList();
    }
    public static void Check()
    {
        var list1 = new List<int> { 1, 2, 3, 4, 5 };
        var expected1 = new List<int> { 25, 9, 1 };
        Debug.Assert(FilterSquareSortDesc(list1).SequenceEqual(expected1));
        var list2 = new List<int> { -3, -2, -1, 0, 4, 6 };
        var expected2 = new List<int> { 9, 1 };
        Debug.Assert(FilterSquareSortDesc(list2).SequenceEqual(expected2));
        Console.WriteLine("All tests passed.");
    }

}

