class DataAnalyzer
{
    public static List<int> CumulativeMin(List<int> numbers)
    {
        List<int> cumulativeMins = new List<int>();
        if (numbers.Count == 0)
        {
            return cumulativeMins;
        }
        int currentMin = numbers[0];
        foreach (int number in numbers)
        {
            if (number < currentMin)
            {
                currentMin = number;
            }
            cumulativeMins.Add(currentMin);
        }
        return cumulativeMins;
