def parse(record):
    # 首先，初始化棋盘和存储对弈信息的字典
    board = [[0 for _ in range(19)] for _ in range(19)]
    game_info = {}

    # 解析对弈信息
    for line in record.strip().split('\n'):
        line = line.strip()
        if line.startswith(';'):
            # 解析棋子的落点
            moves = line.split(';')[1:]  # 移除空字符串
            for move in moves:
                color, pos = move[0], move[2:4]  # 分离颜色和位置
                col, row = ord(pos[0]) - ord('a'), ord(pos[1]) - ord('a')  # 计算数组索引
                board[row][col] = 1 if color == 'B' else 2
        else:
            # 解析其他信息
            tks = line.split('[')
            if len(tks) != 2:
                continue
            key, value = line.split('[')
            game_info[key] = value[:-1]  # 移除末尾的']'

    return board, game_info

