describe('CSS styling', () => {
  let browser;
  let page;

  beforeAll(async () => {
    browser = await puppeteer.launch({args: ['--no-sandbox']});
    page = await browser.newPage();
    await page.setContent(`#<INSERT>`);
  });

  afterAll(async () => {
    await browser.close();
  });

  it('<h1> element should be center aligned with a light gray background', async () => {
    const h1Styles = await page.evaluate(() => {
      const h1 = document.querySelector('h1');
      return {
        textAlign: window.getComputedStyle(h1).textAlign,
        backgroundColor: window.getComputedStyle(h1).backgroundColor
      };
    });

    expect(h1Styles.textAlign).toBe('center');
    expect(h1Styles.backgroundColor).toBe('rgb(240, 240, 240)');
  });

  it('<div> element should be 400px wide with centered text and a blue border', async () => {
    const divStyles = await page.evaluate(() => {
      const div = document.querySelector('div');
      return {
        width: window.getComputedStyle(div).width,
        textAlign: window.getComputedStyle(div).textAlign,
        borderColor: window.getComputedStyle(div).borderColor
      };
    });

    expect(divStyles.width).toBe('400px');
    expect(divStyles.textAlign).toBe('center');
    expect(divStyles.borderColor).toBe('rgb(0, 0, 255)');
  });

  it('<span> text should be bold and turn orange when hovered', async () => {
