import java.util.HashMap;
class Book {
    String title;
    String author;
    String isbn;
    public Book(String title, String author, String isbn) {
        this.title = title;
        this.author = author;
        this.isbn = isbn;
    }
}
public class BookManager {
    static HashMap<String, Book> libraryBooks = new HashMap<>();
    static {
        libraryBooks.put("123456789", new Book("Java Programming", "John Doe", "123456789"));
        libraryBooks.put("987654321", new Book("Python Programming", "Jane Doe", "987654321"));
    }
    public static boolean isBookAvailable(String isbn) {
        return libraryBooks.containsKey(isbn);
    }
    public static void checkAvailability(String[] isbns) {
        for (String isbn : isbns) {
            System.out.println("ISBN " + isbn + ": " + (isBookAvailable(isbn) ? "Available" : "Not Available"));
        }
    }
    public static void main(String[] args) {
        String[] testIsbns = {"123456789", "987654321", "111111111"};
        checkAvailability(testIsbns);
    }
}

