import { describe, expect, it, beforeAll, afterAll } from '@jest/globals';
import puppeteer from 'puppeteer';

describe('Text Box Overflow', () => {
  let browser;
  let page;

  beforeAll(async () => {
    browser = await puppeteer.launch({args: ['--no-sandbox']});
    page = await browser.newPage();
    await page.setContent(`#<INSERT>`);
  });

  it('should display a vertical scrollbar for overflowing content', async () => {
    const longText = Array(200).fill('Overflow test text. ').join('');

    await page.evaluate((text) => {
      document.querySelector('.inner-text').innerText = text;
    }, longText);

    const overflow = await page.evaluate(() => {
      const textBox = document.querySelector('.text-box');
      return textBox.scrollHeight > textBox.clientHeight;
    });

    expect(overflow).toBe(true);
  });

  afterAll(async () => {
    await browser.close();
  });
});

import { describe, expect, it, beforeAll, afterAll } from '@jest/globals';
import puppeteer from 'puppeteer';

describe('不同内边距的 <div> 元素测试', () => {
  let browser;
  let page;

  beforeAll(async () => {
    browser = await puppeteer.launch({args: ['--no-sandbox']});
    page = await browser.newPage();
    await page.setContent(`#<INSERT>`);
  });

  afterAll(async () => {
    await browser.close();
  });

  it('所有方向内边距为10px', async () => {
    const padding = await page.$eval('.padding-all', el => getComputedStyle(el).padding);
    expect(padding).toBe('10px');
  });

  it('顶部和底部内边距30px，左右内边距20px', async () => {
    const paddingTop = await page.$eval('.padding-vertical-horizontal', el => getComputedStyle(el).paddingTop);
    const paddingRight = await page.$eval('.padding-vertical-horizontal', el => getComputedStyle(el).paddingRight);
    expect(paddingTop).toBe('30px');
    expect(paddingRight).toBe('20px');
  });

  it('左边内边距5px，其他方向内边距15px', async () => {
    const paddingLeft = await page.$eval('.padding-except-left', el => getComputedStyle(el).paddingLeft);
    const paddingRight = await page.$eval('.padding-except-left', el => getComputedStyle(el).paddingTop);  // 示例中假设顶部内边距与其他方向相同
    expect(paddingLeft).toBe('5px');
    expect(paddingRight).toBe('15px');
  });

  it('只有顶部内边距为25px', async () => {
    const paddingTop = await page.$eval('.padding-top-only', el => getComputedStyle(el).paddingTop);
    expect(paddingTop).toBe('25px');
  });
});

import { describe, expect, test, beforeAll, afterAll } from '@jest/globals';
import puppeteer from 'puppeteer';

describe('Centered Paragraph', () => {
  let browser;
  let page;

  beforeAll(async () => {
    browser = await puppeteer.launch({args: ['--no-sandbox']});
    page = await browser.newPage();
    await page.setContent(`#<INSERT>`);
  });

  afterAll(async () => {
    await browser.close();
  });

  it('should have a <div> that is a flex container', async () => {
    const divDisplay = await page.evaluate(() => {
      const div = document.querySelector('div');
      return window.getComputedStyle(div).display;
    });

    expect(divDisplay).toBe('flex');
  });

  it('should have a <p> element with yellow background and black text', async () => {
    const pStyles = await page.evaluate(() => {
      const p = document.querySelector('p');
      return {
        backgroundColor: window.getComputedStyle(p).backgroundColor,
        color: window.getComputedStyle(p).color,
        textAlign: window.getComputedStyle(p).textAlign,
        padding: window.getComputedStyle(p).padding
      };
    });

    expect(pStyles.backgroundColor).toBe('rgb(255, 255, 0)'); // yellow
    expect(pStyles.color).toBe('rgb(0, 0, 0)'); // black
    expect(pStyles.textAlign).toBe('center');
    expect(pStyles.padding).toBe('20px'); // assuming there's uniform padding
  });
});

